// Innovium sets these in your MCP server’s environment when it launches it.
const token = process.env.DIWAN_SDK_TOKEN; // bearer token for this connection
const port = process.env.DIWAN_SDK_PORT ?? '28103'; // internal API port
const projectId = process.env.DIWAN_PROJECT_ID; // active project ("" if none)

const BASE_URL = `http://127.0.0.1:${port}/sdk-api`;

// Example: read a file from the active project via the Filesystem area.
async function readProjectFile(filePath) {
  const res = await fetch(`${BASE_URL}/filesystem/read?path=${encodeURIComponent(filePath)}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) {
    throw new Error(`Internal API ${res.status}: ${await res.text()}`);
  }
  return res.json();
}

// Writes and other actions are POST/PUT/PATCH/DELETE with a JSON body:
await fetch(`${BASE_URL}/data-layer/properties/myKey`, {
  method: 'PUT',
  headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
  body: JSON.stringify({ value: 'hello' }),
});
